const REGISTERED_UI_TEXTS = new Set<string>();
const UI_TRANSLATION_LISTENERS = new Set<() => void>();

function languageKey(language: string | null | undefined): string | null {
  if (!language) return null;
  return language.trim().toLowerCase().replace("_", "-").split("-")[0] || null;
}

function notifyUiTranslationListeners(): void {
  UI_TRANSLATION_LISTENERS.forEach((listener) => {
    try {
      listener();
    } catch {}
  });
}

/**
 * Register UI copy discovered by the Babel transform. This includes static
 * Text content and literal input labels/placeholders, never runtime user data.
 */
export function registerUiTexts(texts: string[]): void {
  let added = false;
  for (const text of texts) {
    if (typeof text === "string" && text.trim().length >= 2 && !REGISTERED_UI_TEXTS.has(text)) {
      REGISTERED_UI_TEXTS.add(text);
      added = true;
    }
  }
  if (added) notifyUiTranslationListeners();
}

export function subscribeUiTranslations(listener: () => void): () => void {
  UI_TRANSLATION_LISTENERS.add(listener);
  return () => UI_TRANSLATION_LISTENERS.delete(listener);
}

/**
 * Kept as a compatibility no-op for callers that used to warm the remote
 * translation cache. UI copy is now resolved only from the bundled catalogs.
 */
export function preloadUiTranslations(_language: string): Promise<void> {
  return Promise.resolve();
}

export function translateUi(
  text: string,
  language: string | null | undefined,
  params?: Record<string, string | number>,
): string {
  if (!text) return text;
  const normalized = languageKey(language) ?? "";
  const uiLanguage = LANGUAGE_ALIASES[language?.trim().toLowerCase() ?? ""] ?? LANGUAGE_ALIASES[normalized];
  const semanticEnglish = SEMANTIC_UI_TABLES.en[text];
  const interpolate = (value: string): string =>
    params
      ? value.replace(/\{\{(\w+)\}\}/g, (_, name: string) => String(params[name] ?? `{{${name}}}`))
      : value;

  // Semantic keys always resolve to their English source value when the
  // locale is unset or English, preventing raw key names from leaking during
  // startup before the language preference has loaded.
  if (semanticEnglish) {
    const translatedSemantic = uiLanguage && uiLanguage !== "en"
      ? SEMANTIC_UI_TABLES[uiLanguage]?.[text] ?? semanticEnglish
      : semanticEnglish;
    return interpolate(translatedSemantic);
  }

  if (!language || uiLanguage === "en" || normalized === "en") return text;
  const languageTable = uiLanguage as UiLanguage;
  const leading = text.match(/^\s*/)?.[0] ?? "";
  const trailing = text.match(/\s*$/)?.[0] ?? "";
  const trimmed = text.slice(leading.length, text.length - trailing.length || undefined);
  const translated = COMMON_PLATFORM_PHRASES[languageTable]?.[trimmed]
    ?? APP_UI_TABLES[languageTable]?.[trimmed]
    ?? OFFLINE_PHRASES[languageTable]?.[trimmed]
    ?? TABLES[languageTable]?.[trimmed]
    ?? CORE_TABLES[languageTable]?.[trimmed];
  if (translated) return `${leading}${interpolate(translated)}${trailing}`;

  // Translate a literal UI phrase word-by-word as a local fallback. Keep
  // URLs, handles, product names, numbers, and interpolation-like tokens
  // intact; those are identifiers, not interface copy.
  const words = OFFLINE_WORDS[languageTable] ?? {};
  const localized = trimmed.replace(/[A-Za-zÀ-ÿ]+/g, (word) => {
    const replacement = words[word.toLowerCase()];
    if (!replacement) return word;
    if (word[0] === word[0].toUpperCase() && replacement.length > 0) {
      return replacement[0].toUpperCase() + replacement.slice(1);
    }
    return replacement;
  });
  return `${leading}${interpolate(localized)}${trailing}`;
}

export function setCurrentUiLanguage(language: string | null): void {
  currentUiLanguage = language;
}

export function localizeUi(text: string): string {
  return translateUi(text, currentUiLanguage);
}
